import hashlib
import hmac
import json

from payhook.errors import InvalidNotification


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format."""

    # -- Timestamp validation (common to both v1 and r0 paths) --
    timestamp_str = headers.get("X-Pay-Timestamp")
    if not timestamp_str:
        raise InvalidNotification("Missing X-Pay-Timestamp header")
    try:
        timestamp = int(timestamp_str)
    except (ValueError, TypeError):
        raise InvalidNotification("Malformed X-Pay-Timestamp")
    if abs(now - timestamp) > 300:
        raise InvalidNotification("Stale timestamp")

    # -- Parse JSON body --
    try:
        payload = json.loads(raw_body)
    except (json.JSONDecodeError, ValueError, TypeError):
        raise InvalidNotification("Malformed JSON body")
    if not isinstance(payload, dict):
        raise InvalidNotification("JSON body must be an object")

    # -- Validate required fields --
    for key in ("event_id", "account_id", "amount_minor", "currency"):
        if key not in payload:
            raise InvalidNotification(f"Missing field: {key}")

    event_id = payload["event_id"]
    account_id = payload["account_id"]
    amount_minor = payload["amount_minor"]
    currency = payload["currency"]

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("event_id must be a nonempty string")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("account_id must be a nonempty string")
    # booleans are not amounts (bool is subclass of int in Python)
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("amount_minor must be an integer")
    if amount_minor < 0:
        raise InvalidNotification("amount_minor must be nonnegative")
    if not isinstance(currency, str) or len(currency) != 3 or not currency.isascii() or not currency.isupper() or not currency.isalpha():
        raise InvalidNotification("currency must be three uppercase ASCII letters")

    # -- Signature / receipt verification --
    ts_bytes = timestamp_str.encode("ascii")

    # Try v1 body-based signature first
    v1_verified = False
    sig_header = headers.get("X-Pay-Signature")
    if sig_header and sig_header.startswith("v1="):
        expected_v1 = hmac.new(secret, ts_bytes + b"." + raw_body, hashlib.sha256).hexdigest()
        v1_verified = hmac.compare_digest(expected_v1, sig_header[3:])

    if v1_verified:
        return {
            "event_id": event_id,
            "account_id": account_id,
            "amount_minor": amount_minor,
            "currency": currency,
        }

    # Try r0 receipt path (legacy v0 connector)
    receipt_header = headers.get("X-Pay-Receipt")
    if receipt_header and receipt_header.startswith("r0="):
        expected_r0 = hmac.new(
            secret,
            ts_bytes + b"." + event_id.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        r0_verified = hmac.compare_digest(expected_r0, receipt_header[3:])
        if r0_verified:
            return {
                "event_id": event_id,
                "account_id": account_id,
                "amount_minor": amount_minor,
                "currency": currency,
            }

    raise InvalidNotification("No valid signature or receipt")
